import unittest
from unittest.mock import patch
import catalog
import prices
import routes

class PriceCacheTests(unittest.TestCase):
    def test_currency_switches_and_cache_hits(self):
        for currencies in [('USD', 'EUR'), ('EUR', 'USD')]:
            with self.subTest(currencies=currencies):
                prices.CACHE.clear()
                with patch.object(catalog, 'fetch', wraps=catalog.fetch) as fetch:
                    for _ in range(3):
                        for product in ('book', 'pen'):
                            for currency in currencies:
                                self.assertEqual(
                                    routes.price({'product': product, 'currency': currency}),
                                    {'amount': catalog.PRICES[(product, currency)]},
                                )
                    self.assertEqual(fetch.call_count, 4)
                    self.assertEqual(len(prices.CACHE), 4)
                    for product in ('book', 'pen'):
                        for currency in currencies:
                            self.assertEqual(fetch.call_args_list.count(unittest.mock.call(product, currency)), 1)
        prices.CACHE.clear()

unittest.main()
